import Foundation

extension FavoriteItem {
    static let all: [FavoriteItem] = [
        FavoriteItem(title: "Austria", subtitle: "Europe • Vienna", imageName: "austria", rating: 4,
                     description: "Austria is a landlocked country in Central Europe, famous for the Alps and its imperial past. Vienna was home to Mozart, Beethoven and Strauss, and its coffee houses are part of UNESCO's cultural heritage. In winter the mountains turn into some of the best ski resorts in Europe."),
        FavoriteItem(title: "Brazil", subtitle: "South America • Rio de Janeiro", imageName: "brazil", rating: 5,
                     description: "Brazil is the largest country in South America and the only one where Portuguese is the official language. Rio de Janeiro is known for the Christ the Redeemer statue, Copacabana beach and the world's most famous carnival. Most of the Amazon rainforest lies within Brazil's borders."),
        FavoriteItem(title: "China", subtitle: "Asia • Chongqing", imageName: "china", rating: 3,
                     description: "China is home to one of the oldest continuous civilizations in the world. Chongqing is a huge mountain city on the Yangtze River, famous for its spicy hot pot and neon-lit skyline. The Great Wall, the Forbidden City and the terracotta warriors draw millions of visitors every year."),
        FavoriteItem(title: "Egypt", subtitle: "Africa • Luxor", imageName: "egypt", rating: 5,
                     description: "Egypt has been shaped by the Nile for more than five thousand years. Luxor is often called the world's greatest open-air museum, with the Karnak and Luxor temples and the Valley of the Kings nearby. The pyramids of Giza are the last surviving wonder of the ancient world."),
        FavoriteItem(title: "England", subtitle: "Europe • London", imageName: "england", rating: 2,
                     description: "England is the largest of the four nations of the United Kingdom. London combines royal palaces and Big Ben with some of the best museums in the world, many of them free. It is also the birthplace of Shakespeare and of modern football."),
        FavoriteItem(title: "France", subtitle: "Europe • Paris", imageName: "france", rating: 4,
                     description: "France is one of the most visited countries on Earth. Paris is home to the Eiffel Tower, the Louvre and countless cafés along the Seine. French cuisine, wine and cheese are recognised around the world as part of its cultural identity."),
        FavoriteItem(title: "Germany", subtitle: "Europe • Frankfurt am Main", imageName: "germany", rating: 3,
                     description: "Germany has the largest economy in Europe and a long tradition of engineering and car making. Frankfurt am Main is the country's financial centre, with a skyline of glass towers next to a rebuilt medieval old town. Germany is also known for its castles, Christmas markets and Oktoberfest in Munich."),
        FavoriteItem(title: "India", subtitle: "Asia • Agra", imageName: "india", rating: 5,
                     description: "India is the most populous country in the world and one of the most diverse, with hundreds of languages. Agra is the home of the Taj Mahal, a white marble mausoleum built by Emperor Shah Jahan for his wife. Indian food, cricket and Bollywood films are loved far beyond its borders."),
        FavoriteItem(title: "Israel", subtitle: "Asia • Jerusalem", imageName: "israel", rating: 4,
                     description: "Israel lies on the eastern shore of the Mediterranean Sea. Jerusalem's Old City contains sites holy to Judaism, Christianity and Islam within a few hundred metres of each other. The Dead Sea, on the country's eastern edge, is the lowest point on land on Earth."),
        FavoriteItem(title: "Italy", subtitle: "Europe • Pisa", imageName: "italy", rating: 4,
                     description: "Italy was the heart of the Roman Empire and the birthplace of the Renaissance. Pisa is famous for its Leaning Tower, which began to tilt while it was still being built in the twelfth century. Pizza, pasta and gelato make Italian cuisine one of the most popular in the world."),
        FavoriteItem(title: "South Korea", subtitle: "Asia • Seoul", imageName: "korea", rating: 2,
                     description: "South Korea occupies the southern half of the Korean Peninsula. Seoul is a fast, high-tech capital where ancient palaces stand next to glass skyscrapers. K-pop, Korean dramas and brands like Samsung and Hyundai have made the country famous worldwide."),
        FavoriteItem(title: "Mexico", subtitle: "North America • Mexico City", imageName: "mexico", rating: 3,
                     description: "Mexico was home to great civilizations such as the Maya and the Aztecs. Mexico City is built on the ruins of the Aztec capital Tenochtitlan and is one of the largest cities in the Americas. The country is known for tacos, mariachi music and the colourful Day of the Dead celebrations."),
        FavoriteItem(title: "Morocco", subtitle: "Africa • Casablanca", imageName: "morocco", rating: 5,
                     description: "Morocco sits in North Africa, where the Atlas Mountains meet the Sahara Desert. Casablanca is the country's largest city and home to the Hassan II Mosque, built partly over the Atlantic Ocean. Colourful markets, mint tea and tagine are a big part of everyday Moroccan life."),
        FavoriteItem(title: "Poland", subtitle: "Europe • Gdańsk", imageName: "poland", rating: 4,
                     description: "Poland is a Central European country with a rich and often dramatic history. Gdańsk is a port city on the Baltic Sea with a colourful old town and a long history in amber trade. It is also where the Solidarity movement began, which helped to end communism in Eastern Europe."),
        FavoriteItem(title: "Portugal", subtitle: "Europe • Lisbon", imageName: "portugal", rating: 5,
                     description: "Portugal is the westernmost country of mainland Europe. Its sailors led the Age of Discovery and reached India, Brazil and Japan. Lisbon is known for its hills, yellow trams, azulejo tiles and pastéis de nata."),
        FavoriteItem(title: "Slovenia", subtitle: "Europe • Piran", imageName: "slovenia", rating: 5,
                     description: "Slovenia is a small country between the Alps and the Adriatic Sea, and more than half of it is covered by forest. Piran is a charming Venetian-style town on a narrow peninsula with red roofs and narrow streets. Lake Bled, with its island church, is one of the most photographed places in Europe."),
        FavoriteItem(title: "Spain", subtitle: "Europe • Salamanca", imageName: "spain", rating: 4,
                     description: "Spain is famous for its sunny coasts, flamenco and tapas. Salamanca is home to one of the oldest universities in Europe, and its golden sandstone buildings glow at sunset. Barcelona and Madrid are among the most visited cities on the continent."),
        FavoriteItem(title: "Tunisia", subtitle: "Africa • Tunis", imageName: "tunisia", rating: 5,
                     description: "Tunisia is the northernmost country in Africa, on the Mediterranean coast. Tunis, the capital, has a historic medina that is a UNESCO World Heritage Site. Nearby lie the ruins of ancient Carthage, once a rival of Rome."),
        FavoriteItem(title: "Ukraine", subtitle: "Europe • Ivano-Frankivsk", imageName: "ukraine", rating: 5,
                     description: "Ukraine is the largest country lying entirely within Europe. Ivano-Frankivsk is a cosy city in the west, close to the Carpathian Mountains, with Austro-Hungarian architecture. Ukrainian culture is known for embroidered vyshyvanka shirts, borscht and varenyky."),
        FavoriteItem(title: "United States of America", subtitle: "North America • New York", imageName: "usa", rating: 4,
                     description: "The United States is a federal republic of fifty states stretching from the Atlantic to the Pacific. New York is its largest city, famous for the Statue of Liberty, Times Square and Central Park. Hollywood films, jazz and fast food have spread American culture around the world.")
    ]
}
